{
  "assessment": "The paper provides several quantitative claims that can be abstracted into closed-form experimental worlds. The central claims include: (1) the inverse nuclear spin temperature under dynamic polarization as a function of magnetic field, correlation time, and other parameters (Eq. 8); (2) the electron-induced nuclear spin-lattice relaxation rate (Eq. 13); and (3) the optimal magnetic field for maximum cooling (Eq. 10). These are distinct mechanisms and can be independently modeled. The paper also provides specific parameter values and limits (e.g., short and long correlation time limits) that can be used to set paper parameters. However, some quantities like the exact value of the local field B_L or the hyperfine coupling constant a are not given numerically, so they must be treated as private parameters. The claims are abstractable as closed-form expressions with controllable inputs such as magnetic field, correlation time, and electron spin polarization. The assessment is that these claims are suitable for candidate extraction.",
  "candidates": [
    {
      "family": "nuclear_spin_cooling",
      "title": "Inverse nuclear spin temperature under dynamic polarization",
      "claim": "The inverse nuclear spin temperature beta as a function of magnetic field B, electron correlation time tau_c, and electron spin polarization <S_z> is given by beta = 4<S_z>B/(hbar*gamma_N) / (B^2 + Phi*(T_1eN/tau_c)*(tau_c/T_2e*)^2*B_L^2), where Phi = <1/(1+Omega_e^2*tau_c^2)> + 1/2 and T_1eN is the electron spin relaxation time.",
      "source": {
        "citation": "D. S. Smirnov et al., Cooling and Heating Nuclear Spins by Strongly Localized Electrons, Physical Review Letters (2025), DOI:10.1103/physrevlett.134.016201",
        "journal_doi": "10.1103/physrevlett.134.016201",
        "arxiv_versioned_id": "2406.08296v2",
        "locator": "Eq. (8) in main text",
        "role": "central formula for inverse spin temperature"
      },
      "apparatus": {
        "name": "quantum_dot_nuclear_spin_cooling",
        "description": "A quantum dot with strongly localized electrons interacting with nuclear spins via hyperfine interaction, subject to external magnetic field and optical pumping."
      },
      "background": "Nuclear spins in a quantum dot can be cooled by optically oriented electrons. The efficiency depends on magnetic field and electron correlation time.",
      "initial_observations": [
        "At short correlation times, beta increases with B and then decreases after a maximum.",
        "At long correlation times, the maximum beta decreases and shifts to higher fields."
      ],
      "controls": [
        {
          "name": "magnetic_field",
          "description": "External magnetic field applied along the z-axis",
          "unit": "T",
          "minimum": 0.0,
          "maximum": 10.0
        },
        {
          "name": "correlation_time",
          "description": "Electron correlation time (residence time in the quantum dot)",
          "unit": "s",
          "minimum": 1e-12,
          "maximum": 1e-6
        },
        {
          "name": "electron_spin_polarization",
          "description": "Mean electron spin projection along the magnetic field",
          "unit": "dimensionless",
          "minimum": 0.0,
          "maximum": 0.5
        }
      ],
      "readouts": [
        {
          "name": "inverse_spin_temperature",
          "description": "Inverse nuclear spin temperature",
          "unit": "1/J",
          "resolution": 1e-20
        }
      ],
      "oracle": {
        "kind": "closed_form",
        "outputs": {
          "inverse_spin_temperature": {
            "op": "divide",
            "args": [
              {
                "op": "multiply",
                "args": [
                  4.0,
                  {"var": "electron_spin_polarization"},
                  {"var": "magnetic_field"}
                ]
              },
              {
                "op": "multiply",
                "args": [
                  {"param": "hbar_gamma_N"},
                  {
                    "op": "add",
                    "args": [
                      {
                        "op": "power",
                        "args": [
                          {"var": "magnetic_field"},
                          2.0
                        ]
                      },
                      {
                        "op": "multiply",
                        "args": [
                          {"param": "Phi"},
                          {
                            "op": "divide",
                            "args": [
                              {"param": "T_1eN"},
                              {"var": "correlation_time"}
                            ]
                          },
                          {
                            "op": "power",
                            "args": [
                              {
                                "op": "divide",
                                "args": [
                                  {"var": "correlation_time"},
                                  {"param": "T_2e_star"}
                                ]
                              },
                              2.0
                            ]
                          },
                          {
                            "op": "power",
                            "args": [
                              {"param": "B_L"},
                              2.0
                            ]
                          }
                        ]
                      }
                    ]
                  }
                ]
              }
            ]
          }
        },
        "paper_parameters": {
          "hbar_gamma_N": 1.0e-34,
          "Phi": 1.0,
          "T_1eN": 1.0e-9,
          "T_2e_star": 1.0e-9,
          "B_L": 0.001
        },
        "counterfactual_parameters": {
          "Phi": 0.5
        }
      },
      "diagnostic_conditions": [
        {
          "magnetic_field": 0.0,
          "correlation_time": 1e-9,
          "electron_spin_polarization": 0.1
        },
        {
          "magnetic_field": 0.001,
          "correlation_time": 1e-9,
          "electron_spin_polarization": 0.1
        },
        {
          "magnetic_field": 0.01,
          "correlation_time": 1e-9,
          "electron_spin_polarization": 0.1
        },
        {
          "magnetic_field": 0.1,
          "correlation_time": 1e-9,
          "electron_spin_polarization": 0.1
        },
        {
          "magnetic_field": 1.0,
          "correlation_time": 1e-9,
          "electron_spin_polarization": 0.1
        }
      ],
      "hidden_conditions": [
        {
          "magnetic_field": 0.005,
          "correlation_time": 1e-8,
          "electron_spin_polarization": 0.2
        },
        {
          "magnetic_field": 0.05,
          "correlation_time": 1e-7,
          "electron_spin_polarization": 0.3
        }
      ],
      "budget": 20,
      "max_replicates": 3,
      "confidence_threshold": 0.95,
      "relative_tolerance": 0.1,
      "notes": [
        "The expression for Phi is simplified; in the paper it is given as an average over nuclear spin fluctuations.",
        "The parameters are chosen to reproduce typical orders of magnitude; exact values are not specified in the paper."
      ],
      "counterfactual_change": "Change Phi from 1.0 to 0.5, representing a reduction in spin-spin reservoir heating efficiency."
    },
    {
      "family": "nuclear_spin_relaxation",
      "title": "Electron-induced nuclear spin-lattice relaxation rate",
      "claim": "The electron-induced nuclear spin-lattice relaxation rate 1/T_E is given by 1/T_E = f/(N_I*(B^2+B_L^2)) * (B^2/T_1eN + Phi*tau_c*B_L^2/T_2e*^2).",
      "source": {
        "citation": "D. S. Smirnov et al., Cooling and Heating Nuclear Spins by Strongly Localized Electrons, Physical Review Letters (2025), DOI:10.1103/physrevlett.134.016201",
        "journal_doi": "10.1103/physrevlett.134.016201",
        "arxiv_versioned_id": "2406.08296v2",
        "locator": "Eq. (13) in main text",
        "role": "central formula for relaxation rate"
      },
      "apparatus": {
        "name": "quantum_dot_nuclear_spin_relaxation",
        "description": "A quantum dot with localized electrons causing nuclear spin relaxation in the dark, after optical pumping is switched off."
      },
      "background": "After optical pumping, nuclear spins relax back to equilibrium due to interaction with electrons. The rate depends on magnetic field and correlation time.",
      "initial_observations": [
        "At short correlation times, the relaxation rate decreases with magnetic field as a Lorentzian.",
        "At long correlation times, the relaxation rate is strongly suppressed at high fields."
      ],
      "controls": [
        {
          "name": "magnetic_field",
          "description": "External magnetic field applied along the z-axis",
          "unit": "T",
          "minimum": 0.0,
          "maximum": 10.0
        },
        {
          "name": "correlation_time",
          "description": "Electron correlation time (residence time in the quantum dot)",
          "unit": "s",
          "minimum": 1e-12,
          "maximum": 1e-6
        },
        {
          "name": "filling_factor",
          "description": "Fraction of time the quantum dot is occupied by an electron",
          "unit": "dimensionless",
          "minimum": 0.0,
          "maximum": 1.0
        }
      ],
      "readouts": [
        {
          "name": "relaxation_rate",
          "description": "Electron-induced nuclear spin-lattice relaxation rate",
          "unit": "1/s",
          "resolution": 1e-6
        }
      ],
      "oracle": {
        "kind": "closed_form",
        "outputs": {
          "relaxation_rate": {
            "op": "divide",
            "args": [
              {
                "op": "multiply",
                "args": [
                  {"var": "filling_factor"},
                  {
                    "op": "add",
                    "args": [
                      {
                        "op": "divide",
                        "args": [
                          {
                            "op": "power",
                            "args": [
                              {"var": "magnetic_field"},
                              2.0
                            ]
                          },
                          {"param": "T_1eN"}
                        ]
                      },
                      {
                        "op": "multiply",
                        "args": [
                          {"param": "Phi"},
                          {"var": "correlation_time"},
                          {
                            "op": "power",
                            "args": [
                              {"param": "B_L"},
                              2.0
                            ]
                          },
                          {
                            "op": "divide",
                            "args": [
                              1.0,
                              {
                                "op": "power",
                                "args": [
                                  {"param": "T_2e_star"},
                                  2.0
                                ]
                              }
                            ]
                          }
                        ]
                      }
                    ]
                  }
                ]
              },
              {
                "op": "multiply",
                "args": [
                  {"param": "N_I"},
                  {
                    "op": "add",
                    "args": [
                      {
                        "op": "power",
                        "args": [
                          {"var": "magnetic_field"},
                          2.0
                        ]
                      },
                      {
                        "op": "power",
                        "args": [
                          {"param": "B_L"},
                          2.0
                        ]
                      }
                    ]
                  }
                ]
              }
            ]
          }
        },
        "paper_parameters": {
          "N_I": 1000000.0,
          "T_1eN": 1.0e-9,
          "T_2e_star": 1.0e-9,
          "B_L": 0.001,
          "Phi": 1.0
        },
        "counterfactual_parameters": {
          "Phi": 0.5
        }
      },
      "diagnostic_conditions": [
        {
          "magnetic_field": 0.0,
          "correlation_time": 1e-9,
          "filling_factor": 0.1
        },
        {
          "magnetic_field": 0.001,
          "correlation_time": 1e-9,
          "filling_factor": 0.1
        },
        {
          "magnetic_field": 0.01,
          "correlation_time": 1e-9,
          "filling_factor": 0.1
        },
        {
          "magnetic_field": 0.1,
          "correlation_time": 1e-9,
          "filling_factor": 0.1
        },
        {
          "magnetic_field": 1.0,
          "correlation_time": 1e-9,
          "filling_factor": 0.1
        }
      ],
      "hidden_conditions": [
        {
          "magnetic_field": 0.005,
          "correlation_time": 1e-8,
          "filling_factor": 0.2
        },
        {
          "magnetic_field": 0.05,
          "correlation_time": 1e-7,
          "filling_factor": 0.3
        }
      ],
      "budget": 20,
      "max_replicates": 3,
      "confidence_threshold": 0.95,
      "relative_tolerance": 0.1,
      "notes": [
        "The expression is valid for arbitrary correlation time.",
        "Parameters are chosen to reproduce typical orders of magnitude."
      ],
      "counterfactual_change": "Change Phi from 1.0 to 0.5, representing a reduction in spin-spin reservoir heating efficiency."
    },
    {
      "family": "optimal_field",
      "title": "Optimal magnetic field for maximum nuclear spin cooling",
      "claim": "For large number of nuclei and long correlation times, the optimal magnetic field B_0 for maximum inverse spin temperature is given by B_0 = (1/T_2e*) / sqrt(gamma_e^2 + 4/(tau_c*B_L_tilde)^2), where B_L_tilde = sqrt(3)*B_L.",
      "source": {
        "citation": "D. S. Smirnov et al., Cooling and Heating Nuclear Spins by Strongly Localized Electrons, Physical Review Letters (2025), DOI:10.1103/physrevlett.134.016201",
        "journal_doi": "10.1103/physrevlett.134.016201",
        "arxiv_versioned_id": "2406.08296v2",
        "locator": "Eq. (10) in main text",
        "role": "central formula for optimal field"
      },
      "apparatus": {
        "name": "quantum_dot_optimal_field",
        "description": "A quantum dot with strongly localized electrons, used to determine the magnetic field that maximizes nuclear spin cooling."
      },
      "background": "The efficiency of nuclear spin cooling depends on magnetic field, with an optimal field that maximizes the inverse spin temperature.",
      "initial_observations": [
        "At short correlation times, the optimal field is approximately the local field.",
        "At long correlation times, the optimal field increases with correlation time."
      ],
      "controls": [
        {
          "name": "correlation_time",
          "description": "Electron correlation time (residence time in the quantum dot)",
          "unit": "s",
          "minimum": 1e-12,
          "maximum": 1e-6
        },
        {
          "name": "electron_gyromagnetic_ratio",
          "description": "Electron gyromagnetic ratio",
          "unit": "rad/(s*T)",
          "minimum": 1e10,
          "maximum": 1e12
        }
      ],
      "readouts": [
        {
          "name": "optimal_magnetic_field",
          "description": "Magnetic field that maximizes inverse spin temperature",
          "unit": "T",
          "resolution": 1e-6
        }
      ],
      "oracle": {
        "kind": "closed_form",
        "outputs": {
          "optimal_magnetic_field": {
            "op": "divide",
            "args": [
              {
                "op": "divide",
                "args": [
                  1.0,
                  {"param": "T_2e_star"}
                ]
              },
              {
                "op": "sqrt",
                "args": [
                  {
                    "op": "add",
                    "args": [
                      {
                        "op": "power",
                        "args": [
                          {"var": "electron_gyromagnetic_ratio"},
                          2.0
                        ]
                      },
                      {
                        "op": "divide",
                        "args": [
                          4.0,
                          {
                            "op": "power",
                            "args": [
                              {
                                "op": "multiply",
                                "args": [
                                  {"var": "correlation_time"},
                                  {"param": "B_L_tilde"}
                                ]
                              },
                              2.0
                            ]
                          }
                        ]
                      }
                    ]
                  }
                ]
              }
            ]
          }
        },
        "paper_parameters": {
          "T_2e_star": 1.0e-9,
          "B_L_tilde": 0.001732
        },
        "counterfactual_parameters": {
          "B_L_tilde": 0.003
        }
      },
      "diagnostic_conditions": [
        {
          "correlation_time": 1e-9,
          "electron_gyromagnetic_ratio": 1e11
        },
        {
          "correlation_time": 1e-8,
          "electron_gyromagnetic_ratio": 1e11
        },
        {
          "correlation_time": 1e-7,
          "electron_gyromagnetic_ratio": 1e11
        },
        {
          "correlation_time": 1e-6,
          "electron_gyromagnetic_ratio": 1e11
        }
      ],
      "hidden_conditions": [
        {
          "correlation_time": 5e-9,
          "electron_gyromagnetic_ratio": 2e11
        },
        {
          "correlation_time": 5e-8,
          "electron_gyromagnetic_ratio": 5e10
        }
      ],
      "budget": 10,
      "max_replicates": 3,
      "confidence_threshold": 0.95,
      "relative_tolerance": 0.1,
      "notes": [
        "This formula is valid for large N_I and long correlation times.",
        "The parameter B_L_tilde is sqrt(3)*B_L."
      ],
      "counterfactual_change": "Change B_L_tilde from 0.001732 to 0.003, representing a stronger local field."
    }
  ]
}
